"""Every scenario in conformance/guarded-apply.v1.json, generated by the TypeScript editor."""
import json
import unittest
from pathlib import Path

from super_editor import Editor

DATA = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "guarded-apply.v1.json").read_text())


class Conformance(unittest.TestCase):
    def test_scenarios(self):
        steps = 0
        for scenario in DATA["scenarios"]:
            editor = Editor(scenario["initial"])
            for i, step in enumerate(scenario["steps"]):
                with self.subTest(scenario=scenario["name"], step=i):
                    got = editor.apply(step["transaction"], step["now"])
                    expect = step["expect"]
                    self.assertEqual(got["ok"], expect["ok"])
                    if expect["ok"]:
                        self.assertEqual(got.get("duplicate"), expect.get("duplicate"))
                        self.assertEqual(got["document"], expect["document"])
                    else:
                        self.assertEqual(got["issues"], expect["issues"])
                        self.assertEqual(got["currentRevision"], expect["currentRevision"])
                steps += 1
        self.assertGreaterEqual(steps, 250)

    def test_failures_and_duplicates_are_covered(self):
        outcomes = [s["expect"] for sc in DATA["scenarios"] for s in sc["steps"]]
        codes = {i["code"] for o in outcomes if not o["ok"] for i in o["issues"]}
        self.assertTrue({"conflict", "not-found", "duplicate", "validation"} <= codes)
        self.assertTrue(any(o["ok"] and o.get("duplicate") for o in outcomes))


if __name__ == "__main__":
    unittest.main()
